from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n; self.g = [[] for _ in range(n)]; self.E = []
    def add(self, u, v, c):
        self.g[u].append(len(self.E)); self.E.append([v, c])
        self.g[v].append(len(self.E)); self.E.append([u, 0])
    def bfs(self, s, t):
        self.lv = [-1]*self.n; self.lv[s] = 0; q = deque([s])
        while q:
            u = q.popleft()
            for i in self.g[u]:
                v, c = self.E[i]
                if c and self.lv[v] < 0:
                    self.lv[v] = self.lv[u]+1; q.append(v)
        return self.lv[t] >= 0
    def dfs(self, u, t, f):
        if u == t: return f
        while self.it[u] < len(self.g[u]):
            i = self.g[u][self.it[u]]; v, c = self.E[i]
            if c and self.lv[v] == self.lv[u]+1:
                d = self.dfs(v, t, min(f, c))
                if d:
                    self.E[i][1] -= d; self.E[i^1][1] += d; return d
            self.it[u] += 1
        return 0
    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            self.it = [0]*self.n
            while True:
                f = self.dfs(s, t, float('inf'))
                if not f: break
                flow += f
        return flow
